linkList.script:
debugger
var value = input1.Value;
if (value !== '') {
    FuzzyQueryRole(value, function (cb) {
        if (cb.length === 0) {
            Table1.SetData('');
        } else {
            var tableData = [];

            for (let i = 0; i < cb.length; i++) {
                var gridData = {
                    角色名称: cb[i].name,
                    描述: cb[i].comment,
                    状态: cb[i].status ? '启用' : '未启用'
                };
                tableData.push(gridData);
            }
            Table1.SetData(tableData);
            Table1.$vm.currentPage = 1;
        }

    });
}
else {
    var tableData = [];
    QueryRoleObject('', function (cb) {
        for (var index = 0; index < cb.length; index++) {
            var gridData = {};
            gridData['角色名称'] = cb[index]['name'];
            gridData['描述'] = cb[index]['comment'];
            gridData['状态'] = cb[index]['status'];
            gridData['用户'] = cb[index]['userGroupMsg'];

            if (gridData['状态'] === true) {
                gridData['状态'] = '启用';
            }
            else {
                gridData['状态'] = '未启用';
            }
            tableData.push(gridData);
        }
        Table1.SetData(tableData);
        Table1.$vm.currentPage = 1;
    });
}

