/*id为easyui控件的id*/

var forzenColumns = [[
]];
var pageName = '权限管理';
this.table({
    height: '36px',
    cellStyle: function (row, column, rowIndex, columnIndex) {
    }, columns: [

        { prop: '', label: '', align: "left", minWidth: '100', type: 'selection', columnKey: '' },
        { prop: '角色名称', label: '角色名称', minWidth: '100', align: 'center' },
        { prop: '描述', label: '描述', minWidth: '100', align: 'center' },
        { prop: '状态', label: '状态', minWidth: '100', align: 'center' },
        {
            prop: '操作', label: '操作', align: "left", minWidth: '200', type: '', columnKey: '', fixed: false, plugins: [
                //编辑角色
                {
                    pluginType: 'button', text: '编辑', type: 'info', icon: 'el-icon-edit', click: function (scope) {
                        //debugger
                        //根据权限描述判断角色的控制权限
                        debugger
                        SetAuthDescObject('权限管理', '编辑角色', function (cb) {
                            // console.log('cb========================' + cb)
                            if (cb.errorCode !== 0) {
                                var mode = 'alert';
                                var message = '当前用户无此对象操作权限！';
                                var options = {
                                    title: '提示',
                                    message: message,
                                    type: 'warning'
                                };
                                ShowMsgBox(mode, options, function (res) {
                                    // console.log(res)
                                });
                            }
                            if (cb.errorCode === 0) {
                                var style = {
                                    title_bgcolor: '#f8f8f8',
                                    operation_bgcolor: '#f8f8f8',
                                    confirmButton_bgcolor: '#0071ce',
                                    cancelButton_bgcolor: '#d8d8d8'
                                };
                                //权限校验通过后弹出修改角色弹窗
                                ShowModifyRoleBox(scope.row['角色名称'], function (cb) {
                                    //console.log(cb)
                                    //判断回调函数的内容
                                    if (cb !== null) {
                                        FuzzyQueryRole(self.$ParentChildren.input1.Value, function (cb) {
                                            if (cb.length == 0) {
                                                Table1.SetData('');
                                            } else {
                                                var tableData = [];

                                                for (let i = 0; i < cb.length; i++) {
                                                    var gridData = {
                                                        角色名称: cb[i].name,
                                                        描述: cb[i].comment,
                                                        状态: cb[i].status ? '启用' : '未启用'
                                                    }
                                                    tableData.push(gridData);
                                                }
                                                self.$ParentChildren.Table1.SetData(tableData);
                                            }
                                        });
                                    }
                                }, style);
                            }
                        });
                    }
                },
                //删除角色
                {
                    pluginType: 'button', text: '删除', type: 'danger', icon: 'el-icon-close', click: function (scope) {
                        debugger
                        //根据权限描述判断角色的控制权限
                        SetAuthDescObject(pageName, '删除角色', function (cb) {
                            //console.log('cb========================' + cb)
                            //当角色无当前权限描述，给出提示，错误码为-1
                            if (cb.errorCode !== 0) {
                                var mode = 'alert';
                                var message = '当前用户无此对象操作权限！';
                                var options = {
                                    title: '提示',
                                    message: message,
                                    type: 'warning'
                                };
                                ShowMsgBox(mode, options, function (res) {
                                    //console.log(res)
                                });
                            }
                            //当错误码为0时，代表有权限，弹出确认删除角色的弹窗showmsgbox
                            if (cb.errorCode === 0) {
                                var mode = 'confirm';
                                var message = '确认要删除' + scope.row['角色名称'] + '吗？';
                                var options = {
                                    title: '提示',
                                    message: message,
                                    type: 'warning'
                                };
                                ShowMsgBox(mode, options, function (res) {
                                    //点击确认按钮时
                                    if (res.action == 'confirm') {
                                        debugger
                                        //console.log('scope.row==========================' + scope.row['角色名称'])
                                        var roleName = scope.row['角色名称'];
                                        var roleArr = [];
                                        //删除角色时可能时多个角色，所以是数组array类型
                                        roleArr.push(roleName);
                                        //console.log('rowarr==========================' + roleArr)
                                        //执行删除函数
                                        DeleteRoleObject(roleArr, function (cb) {
                                            //console.log(cb)
                                            if (cb !== null && cb.errorCode != -1) {
                                                var options =
                                                {
                                                    message: '删除成功',
                                                    type: 'success',
                                                    offset: 20,
                                                    duration: 2000,
                                                    showClose: false
                                                }
                                                ShowMessage(options); // 展示消息提示弹窗

                                                FuzzyQueryRole(self.$ParentChildren.input1.Value, function (cb) {
                                                    if (cb.length === 0) {
                                                        Table1.SetData('');
                                                    } else {
                                                        var tableData = [];

                                                        for (let i = 0; i < cb.length; i++) {
                                                            var gridData = {
                                                                角色名称: cb[i].name,
                                                                描述: cb[i].comment,
                                                                状态: cb[i].status ? '启用' : '未启用'
                                                            }
                                                            tableData.push(gridData);
                                                        }
                                                        self.$ParentChildren.Table1.SetData(tableData);
                                                    }
                                                });
                                            }
                                            else if (cb.errorCode == -1) {
                                                var options =
                                                {
                                                    message: '当前角色已关联用户，不可删除',
                                                    type: 'error',
                                                    offset: 20,
                                                    duration: 2000,
                                                    showClose: false
                                                }
                                                ShowMessage(options); // 展示消息提示弹窗
                                                //alert("当前角色已关联用户，不可删除");
                                            }
                                        });
                                    }
                                    else {
                                        var options =
                                        {
                                            message: '取消删除',
                                            type: 'info',
                                            offset: 20,
                                            duration: 2000,
                                            showClose: true
                                        }
                                        ShowMessage(options); // 展示消息提示弹窗
                                    }
                                });

                            }
                        });
                    }
                },
                //分配用户
                {
                    pluginType: 'button', text: '分配用户', type: 'success', icon: 'el-icon-s-custom', click: function (scope) {
                        debugger
                        //根据权限描述判断角色的控制权限
                        SetAuthDescObject(pageName, '分配用户', function (cb) {
                            //console.log('cb========================' + cb)
                            //当角色无当前权限描述，给出提示，错误码为-1
                            if (cb.errorCode === -1) {
                                var mode = 'alert';
                                var message = '当前用户无此对象操作权限！';
                                var options = {
                                    title: '提示',
                                    message: message,
                                    type: 'warning'
                                }
                                ShowMsgBox(mode, options, function (res) {
                                    //console.log(res)
                                });
                            }
                            //当错误码为0时，代表有权限，弹出确认删除角色的弹窗showmsgbox
                            if (cb.errorCode === 0) {
                                var styleConfig = {
                                title_gcolor:'#E6E6FA',
                                main_bgcolor:'#E6E6FA',
                                operation_bgcolor:'#E6E6FA',
                                confirmButton_bgcolor:'4B0082',
                                cancelButton_bgcolor:'FFFOF5'
                            }
                            ShowUserLinkRoleBox(scope.row.角色名称,function(res){
                                console.log(res);
                            },styleConfig);
                            }
                        });
                    }
                },
            ]
        },
        //{ prop: '用户', label: '用户', minWidth: '100', align: 'center' },
    ],
    data: []
});
